     1	// Kulturhuset Stockholm Scraper
     2	// Fetches events from Kulturhuset's Elasticsearch API
     3	
     4	const ELASTIC_SEARCH_URL = 'https://elastic.kulturhusetstadsteatern.se/khst-events';
     5	
     6	/**
     7	 * Map Kulturhuset event to internal format
     8	 * @param {Object} event - Raw event from Elasticsearch
     9	 * @returns {Object} - Internal event format
    10	 */
    11	function mapKulturhusetEvent(event) {
    12	  const source = event._source;
    13	  
    14	  // Extract date and time - store as full ISO timestamp with timezone
    15	  // Kulturhuset API returns dates like "2026-03-26T17:30:00+01:00" (local Stockholm time)
    16	  // We need to preserve this timezone info for correct sorting/filtering
    17	  let date = '';
    18	  let time = '';
    19	  let start_time_iso = '';
    20	  
    21	  if (source.tixStartDate) {
    22	    const startDate = new Date(source.tixStartDate);
    23	    // Store as ISO string with timezone info (converts to UTC)
    24	    start_time_iso = startDate.toISOString();
    25	    date = start_time_iso.split('T')[0];
    26	    time = startDate.toTimeString().substring(0, 5);
    27	  }
    28	  
    29	  // Extract venue
    30	  const venues = source.tixVenue || [];
    31	  const venue = venues[0]?.label || 'Kulturhuset Stadsteatern';
    32	  
    33	  // Extract location/area
    34	  const locations = source.drupalLocation || [];
    35	  const area = locations[0]?.label || 'Stockholm';
    36	  
    37	  // Extract description
    38	  const descriptions = source.drupalLeadText || [];
    39	  const description = descriptions[0]?.value || '';
    40	  
    41	  // Extract URL
    42	  const url = source.drupalLink || '';
    43	  
    44	  // Extract title
    45	  const title = source.drupalTitle || source.tixName || 'Untitled Event';
    46	  
    47	  // Map category
    48	  const categories = source.drupalCategory || [];
    49	  const categoryLabel = categories[0]?.label?.toLowerCase() || '';
    50	  const category = mapCategory(categoryLabel);
    51	  
    52	  // Generate unique ID
    53	  const id = `kh-${source.tixEventId || source.drupalId || Math.random().toString(36).substr(2, 9)}`;
    54	  
    55	  return {
    56	    id,
    57	    title,
    58	    date,
    59	    time,
    60	    start_time: start_time_iso,  // Full ISO timestamp for correct storage
    61	    venue,
    62	    area,
    63	    address: '',
    64	    description: description.substring(0, 500),
    65	    url,
    66	    category,
    67	    source: 'kulturhuset',
    68	  };
    69	}
    70	
    71	/**
    72	 * Map Kulturhuset category to internal category
    73	 * @param {string} label - Category label from Kulturhuset
    74	 * @returns {string} - Internal category
    75	 */
    76	function mapCategory(label) {
    77	  const categoryMap = {
    78	    'teater': 'culture',
    79	    'musik': 'music',
    80	    'konsert': 'music',
    81	    'dans': 'culture',
    82	    'film': 'culture',
    83	    'litteratur': 'culture',
    84	    'konst': 'culture',
    85	    'utställning': 'culture',
    86	    'barn & ung': 'barn',
    87	    'barn': 'barn',
    88	    'familj': 'barn',
    89	    'sport': 'sports',
    90	    'mat & dryck': 'food',
    91	    'food': 'food',
    92	    'nattliv': 'nightlife',
    93	    'skapa': 'culture',
    94	    'för skolan': 'barn',
    95	  };
    96	  
    97	  return categoryMap[label] || 'culture';
    98	}
