   100	interface KulturhusetOptions {
   101	  limit?: number;
   102	  page?: number;
   103	  fetchAll?: boolean;
   104	}
   105	
   106	/**
   107	 * Fetch events from Kulturhuset Elasticsearch API
   108	 * @param {KulturhusetOptions} options - Options (limit, page, fetchAll)
   109	 * @param {number} options.limit - Max events per page (default 100)
   110	 * @param {number} options.page - Page number (default 0)
   111	 * @param {boolean} options.fetchAll - Fetch all pages until no more events (default false)
   112	 * @returns {Promise<Object[]>} - Array of events
   113	 */
   114	export async function fetchKulturhusetEvents(options: KulturhusetOptions = {}) {
   115	  const { limit = 100, page = 0, fetchAll = false } = options;
   116	  
   117	  if (fetchAll) {
   118	    // Fetch all events using pagination
   119	    const allEvents: ReturnType<typeof mapKulturhusetEvent>[] = [];
   120	    let currentPage = 0;
   121	    let hasMore = true;
   122	    
   123	    while (hasMore) {
   124	      const pageEvents = await fetchPage(currentPage, limit);
   125	      if (pageEvents.length === 0) {
   126	        hasMore = false;
   127	      } else {
   128	        allEvents.push(...pageEvents);
   129	        currentPage++;
   130	        // Safety limit to prevent infinite loops
   131	        if (currentPage >= 100) {
   132	          console.log('[kulturhuset] Reached max pages (100), stopping');
   133	          break;
   134	        }
   135	      }
   136	    }
   137	    
   138	    console.log(`[kulturhuset] Fetched ${allEvents.length} total events across ${currentPage} pages`);
   139	    return allEvents;
   140	  }
   141	  
   142	  return fetchPage(page, limit);
   143	}
   144	
   145	async function fetchPage(page: number, limit: number): Promise<ReturnType<typeof mapKulturhusetEvent>[]> {
   146	  const query = {
   147	    size: limit,
   148	    from: page * limit,
   149	    query: {
   150	      bool: {
   151	        must: [
   152	          {
   153	            range: {
   154	              tixStartDate: {
   155	                gte: 'now',  // Only future events
   156	              },
   157	            },
   158	          },
   159	        ],
   160	      },
   161	    },
   162	    sort: [
   163	      { tixStartDate: { order: 'asc' } },
   164	    ],
   165	  };
   166	  
   167	  try {
   168	    const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
   169	      method: 'POST',
   170	      headers: {
   171	        'Content-Type': 'application/json',
   172	        'User-Agent': 'EventPulse/1.0',
   173	      },
   174	      body: JSON.stringify(query),
   175	    });
   176	    
   177	    if (!response.ok) {
   178	      throw new Error(`Kulturhuset API error: ${response.status}`);
   179	    }
   180	    
   181	    const data = await response.json();
   182	    
   183	    if (!data.hits || !data.hits.hits) {
   184	      return [];
   185	    }
   186	    
   187	    return data.hits.hits.map(mapKulturhusetEvent);
   188	  } catch (error) {
   189	    console.error('Kulturhuset scraper error:', error);
   190	    throw error;
   191	  }
   192	}
   193	
   194	/**
   195	 * Test function - fetches and logs first 5 events
   196	 */
   197	export async function testScraper() {
   198	  console.log('Testing Kulturhuset scraper (Elasticsearch API)...');
   199	  const events = await fetchKulturhusetEvents({ limit: 5 });
   200	  
   201	  console.log(`Found ${events.length} events from Kulturhuset:`);
   202	  events.forEach((event, i) => {
   203	    console.log(`\n--- Event ${i + 1} ---`);
   204	    console.log(`Title: ${event.title}`);
   205	    console.log(`Date: ${event.date} ${event.time}`);
   206	    console.log(`Venue: ${event.venue}`);
   207	    console.log(`URL: ${event.url}`);
   208	  });
   209	  
   210	  return events;
   211	}
